import sqlite3
import time
from dataclasses import dataclass

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("feature-flags")

DB_PATH = "flags.db"


@dataclass
class CreateFlagResult:
    flag_key: str
    created: bool
    message: str


@mcp.tool()
def create_feature_flag(flag_key: str, description: str, default_enabled: bool = False) -> CreateFlagResult:
    connection = sqlite3.connect(DB_PATH)
    try:
        existing_row = connection.execute(
            "SELECT 1 FROM flags WHERE flag_key = ?", (flag_key,)
        ).fetchone()
        if existing_row:
            return CreateFlagResult(flag_key=flag_key, created=False, message="Flag already exists")
        connection.execute(
            "INSERT INTO flags (flag_key, description, default_enabled, created_at) VALUES (?, ?, ?, ?)",
            (flag_key, description, int(default_enabled), int(time.time())),
        )
        connection.commit()
        return CreateFlagResult(flag_key=flag_key, created=True, message="Flag created")
    finally:
        connection.close()
